#include <bits/stdc++.h>
using namespace std;

int main(){
    int n;
    scanf("%d",&n);
    vector<int> p(n);
    for(int i=0;i<n;i++) scanf("%d",&p[i]);

    if(n<=2){
        // already sorted or just print 0
        // check if sorted
        bool sorted=true;
        for(int i=0;i<n;i++) if(p[i]!=i+1) sorted=false;
        if(sorted){printf("0\n");return 0;}
        // n=2: x+y<2, x>0,y>0 impossible. So n=2 must already be sorted.
        printf("0\n");return 0;
    }

    vector<pair<int,int>> ops;

    auto apply=[&](int x,int y){
        ops.push_back({x,y});
        vector<int> np;
        for(int i=n-y;i<n;i++) np.push_back(p[i]);
        for(int i=x;i<n-y;i++) np.push_back(p[i]);
        for(int i=0;i<x;i++) np.push_back(p[i]);
        p=np;
    };

    for(int i=0;i<n-2;i++){
        int j=-1;
        for(int k=0;k<n;k++) if(p[k]==i+1){j=k;break;}
        if(j==i) continue;

        // Move element from position j to position i
        // Step 1: move to position n-1
        if(j<n-1){
            // x=j+1, y=n-2-j: suffix=[n-(n-2-j)..n-1]=[j+2..n-1], middle=[j+1..j+1], prefix=[0..j]
            // result: [j+2..n-1][j+1..j+1][0..j] -> element at j is now at position n-1
            // x+y = j+1+n-2-j = n-1 < n ✓ (as long as n>=2)
            // y=n-2-j >= 0 requires j<=n-2, which is true since j<n-1
            // But if y=0 that's invalid. y=n-2-j=0 means j=n-2.
            if(j==n-2){
                // x=1, y=1: move last to front, first to back
                // result: [p[n-1]][p[1]..p[n-2]][p[0]] -> element at n-2 is still at n-2... 
                // Just use x=n-1, y=1: [p[n-1]][p[n-1]...] no.
                // x=j+1=n-1, y=1, x+y=n, invalid.
                // Use x=1,y=1: suffix=[n-1], middle=[1..n-2], prefix=[0]. Elem at n-2 -> pos n-2. Hmm.
                apply(1,1); // now element was at n-2, now at n-2 still? No: new array=[p[n-1],p[1],...,p[n-2],p[0]]. Element at n-2 goes to position n-2. Useless. 
                // Instead, do apply(j,1) to rotate it to position n-1
                // Undo: let me not apply. Actually let me restart logic.
                j=-1;for(int k=0;k<n;k++)if(p[k]==i+1){j=k;break;}
            } else {
                apply(j+1, n-2-j);
                j=n-1;
            }
        }
        // Refresh j
        j=-1;for(int k=0;k<n;k++)if(p[k]==i+1){j=k;break;}
        if(j==i) continue;
        // Now try to place at position i
        if(j==n-1 && i+1<n-1){
            apply(i+1,1); // suffix=[n-1], middle=[i+1..n-2], prefix=[0..i]
            // element at n-1 goes to position 0... then position i needs another step
            // After: [p[n-1], p[i+1],...,p[n-2], p[0],...,p[i]]
            // element is at position 0, need it at position i
            j=0;
        } else if(j==n-1 && i+1==n-1){
            apply(i,1);
            continue;
        }
        j=-1;for(int k=0;k<n;k++)if(p[k]==i+1){j=k;break;}
        if(j==i) continue;
        if(j==0 && n-1-i>0 && 1+n-1-i<n){
            apply(1,n-1-i);
            continue;
        }
        // General fallback: try harder
        j=-1;for(int k=0;k<n;k++)if(p[k]==i+1){j=k;break;}
        if(j!=i){
            if(j>0&&j<n-1&& j>=1 && n-1-j>=1){
                apply(j,1);
                j=-1;for(int k=0;k<n;k++)if(p[k]==i+1){j=k;break;}
            }
            if(j!=i && j<n && i<n){
                int y2=n-1-i; if(y2>0 && 1+y2<n){apply(1,y2);}
            }
        }
    }

    printf("%d\n",(int)ops.size());
    for(auto&[a,b]:ops) printf("%d %d\n",a,b);
}
